import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as r,c as l,o as n,af as t,b as c,G as a,w as o,a as h,ag as p}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const A=JSON.parse('{"title":"Tech Map: A Dependency-Driven Knowledge Map","description":"The v6 entry point of the tech track — the model-lifecycle chain and the systems-engineering chain converge at Inference, reading the world and writing the world are separated, and protocols are grouped by connection direction; ten groups ordered by dependency, entered from symptoms in two hops.","frontmatter":{"title":"Tech Map: A Dependency-Driven Knowledge Map","description":"The v6 entry point of the tech track — the model-lifecycle chain and the systems-engineering chain converge at Inference, reading the world and writing the world are separated, and protocols are grouped by connection direction; ten groups ordered by dependency, entered from symptoms in two hops.","domain":"tech","tags":["tech","orientation","map"],"navOrder":1,"topicId":"tech-map","layer":"0","status":"canonical","nodeType":"resource","owner":"learn-ai","externalOwners":[],"prerequisites":[],"next":["complexity-ladder","site-boundaries","model-lifecycle-bridge"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/index.md","filePath":"tech/index.md","lastUpdated":1791123021000}'),u={name:"tech/index.md"};function g(m,e,f,b,y,w){const i=r("Mermaid"),s=r("SymptomRouter");return n(),l("div",null,[e[1]||(e[1]=t('<blockquote><p><strong>Group</strong>: 0 · Orientation and Boundaries | <strong>Previous layer exit</strong>: none | <strong>This page exit</strong>: can locate the problem domain, state its dependencies and exits, and enter the right group <strong>Prerequisites</strong>: none (site entry) | <strong>Next</strong>: <a href="./00-map/complexity-ladder.html">Complexity Decision Ladder</a> · <a href="./00-map/site-boundaries.html">Site Boundaries and Knowledge Ownership</a> · <a href="./01-model-lifecycle/">Model Lifecycle (Bridge)</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>BLUF</strong>: this is a <strong>dependency-driven knowledge map</strong>. The v6 organizing logic is not &quot;classify by technology noun&quot; but three structural questions:</p><ol><li><strong>Where the two chains converge</strong> — the model-lifecycle chain (data → pretraining → post-training) and the AI systems-engineering chain (integration → context → grounding/action → …) converge at <strong>Inference</strong>: every line of AI application code you write starts from the left chain&#39;s end. The left chain&#39;s deep internals belong to <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>; the right chain is this repo&#39;s canonical spine.</li><li><strong>Why reading the world and writing the world are separated</strong> — Grounding (retrieval, citation, updates) and Action (tools, execution, permissions) both &quot;connect the model to things outside the model&quot;, but their failure modes are opposite: a read fails by <strong>answering wrongly</strong>; a write fails by <strong>breaking things</strong>. The acceptance criteria differ accordingly (correct citations vs restricted permissions), which splits them into <a href="./04-grounding/">04-grounding</a> and <a href="./05-action/">05-action</a>.</li><li><strong>Why protocols are grouped by connection direction</strong> — MCP, A2A, ACP, and AG-UI are not competitors; each owns one connection direction (Agent↔tools, Agent↔Agent, editor↔coding agent, Agent↔UI). The first selection question is &quot;what are the two sides I&#39;m connecting&quot;, not &quot;which protocol is hotter&quot; — see <a href="./07-interoperability/">07-interoperability</a>.</li></ol><p>This map answers one question: <strong>where you are stuck right now, and where to go next.</strong> It teaches no individual technology — every group and topic has its own five-part chapter (Overview → Usage → Principles → Development → Resource Library).</p><h3 id="mental-model-two-chains-converge-read-and-write-split" tabindex="-1">Mental model: two chains converge, read and write split <a class="header-anchor" href="#mental-model-two-chains-converge-read-and-write-split" aria-label="Permalink to &quot;Mental model: two chains converge, read and write split&quot;">​</a></h3>',6)),(n(),c(p,null,{default:o(()=>[a(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20ML%5B%22Model-lifecycle%20chain%20%E2%80%94%20deep%20internals%20belong%20to%20Learn%20LLM%22%5D%0A%20%20%20%20%20%20%20%20M1%5B%22Data%20%2F%20Pretraining%22%5D%20--%3E%20M2%5B%22Post-training%3Cbr%2F%3ESFT%20%C2%B7%20RLHF%20%C2%B7%20PEFT%22%5D%0A%20%20%20%20end%0A%20%20%20%20M2%20%3D%3D%3E%20INF%5B%22Inference%3Cbr%2F%3Ethe%20chains%20converge%20here%22%5D%0A%20%20%20%20subgraph%20SE%5B%22AI%20systems-engineering%20chain%20%E2%80%94%20this%20repo's%20canonical%20spine%22%5D%0A%20%20%20%20%20%20%20%20INF%20--%3E%20C%5B%2202%20Inference%20%26%20Interface%3Cbr%2F%3Ecalls%20and%20product%20integration%22%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%20CT%5B%2203%20Context%3Cbr%2F%3Econtrollable%20input%2Foutput%22%5D%0A%20%20%20%20%20%20%20%20CT%20--%3E%20G%5B%2204%20Grounding%20%C2%B7%20reading%20the%20world%3Cbr%2F%3Eretrieval%20%C2%B7%20citation%20%C2%B7%20updates%22%5D%0A%20%20%20%20%20%20%20%20CT%20--%3E%20A%5B%2205%20Action%20%C2%B7%20writing%20the%20world%3Cbr%2F%3Etools%20%C2%B7%20execution%20%C2%B7%20permissions%22%5D%0A%20%20%20%20%20%20%20%20G%20--%3E%20AG%5B%2206%20Agent%20Systems%3Cbr%2F%3Eruntime%20%C2%B7%20state%20%C2%B7%20collaboration%22%5D%0A%20%20%20%20%20%20%20%20A%20--%3E%20AG%0A%20%20%20%20%20%20%20%20AG%20--%3E%20IOP%5B%2207%20Interoperability%3Cbr%2F%3Eprotocols%20by%20connection%20direction%22%5D%0A%20%20%20%20%20%20%20%20IOP%20--%3E%20P%5B%2208%20Production%3Cbr%2F%3Eevidence%20%C2%B7%20version%20axes%20%C2%B7%20operations%22%5D%0A%20%20%20%20end%0A%20%20%20%20P%20-.%20%22observe%20%C2%B7%20feed%20back%20%C2%B7%20version-evolve%22%20.-%3E%20ML%0A%20%20%20%20ADV%5B%2209%20Advanced%20(bridge)%3Cbr%2F%3Einterpretability%20%C2%B7%20reasoning%20%C2%B7%20frontier%20architectures%20%C2%B7%20multimodal%22%5D%20-.%20deep%20water%2C%20jump%20as%20needed%20.-%3E%20ML%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>Arrows show the <strong>default dependency order</strong>, not a hard runtime constraint: a RAG service may pass only through 02/03/04; a tool script may pass only through 02/03/05. Implementation always falls back to the lowest complexity that meets acceptance.</p><h3 id="ten-group-navigation-table" tabindex="-1">Ten-group navigation table <a class="header-anchor" href="#ten-group-navigation-table" aria-label="Permalink to &quot;Ten-group navigation table&quot;">​</a></h3><p>Groups appear in group-number order (00 → 09), with the three off-spine exits (appendices / Recipes / Resources) at the end:</p><table tabindex="0"><thead><tr><th>Group</th><th>What question it answers</th><th>Core topics</th><th>Depends on</th><th>Exit</th></tr></thead><tbody><tr><td><a href="./00-map/complexity-ladder.html">00-map</a> Orientation &amp; Map</td><td>Where do I start, and what is out of scope here?</td><td>the map, complexity ladder, site boundaries</td><td>none</td><td>can locate the problem domain and the next entry</td></tr><tr><td><a href="./01-model-lifecycle/">01-model-lifecycle</a> Model Lifecycle (bridge)</td><td>Where did this model come from, and which of my decisions does it affect?</td><td>the engineering impact of SFT / RLHF / PEFT</td><td>00</td><td>knows when prompts are not enough and which Learn LLM chapter holds the deep water</td></tr><tr><td><a href="./02-inference-interface/">02-inference-interface</a> Inference &amp; Interface</td><td>How do I wire a model call into a product?</td><td>model-api, streaming, structured output, session &amp; UI, edge</td><td>00–01</td><td>a cancellable, observable end-to-end interaction</td></tr><tr><td><a href="./03-context/">03-context</a> Context</td><td>How do I make input and output controllable?</td><td>prompts, context engineering, session memory</td><td>02</td><td>can write and validate schemas; knows how failure is accepted</td></tr><tr><td><a href="./04-grounding/">04-grounding</a> Grounding (reading the world)</td><td>How do answers get evidence?</td><td>embeddings &amp; retrieval, RAG, advanced retrieval</td><td>02–03</td><td>a traceable retrieval chain and a re-runnable update pipeline</td></tr><tr><td><a href="./05-action/">05-action</a> Action (writing the world)</td><td>How do I execute actions safely?</td><td>tool-calling contract, tool execution</td><td>03</td><td>permission-restricted, idempotent, reversible actions</td></tr><tr><td><a href="./06-agent-systems/">06-agent-systems</a> Agent Systems</td><td>How do I build multi-step, recoverable, approval-gated autonomy?</td><td>runtime, workflows, multi-agent, skills, state &amp; recovery</td><td>04–05</td><td>can restrict permissions, pause/resume tasks</td></tr><tr><td><a href="./07-interoperability/">07-interoperability</a> Interoperability</td><td>How do I connect across boundaries?</td><td>MCP / A2A / ACP / AG-UI by connection direction</td><td>05–06</td><td>can pick a protocol by connection direction and justify rejecting the rest</td></tr><tr><td><a href="./08-production/">08-production</a> Production</td><td>How do I prove it can launch and keep running?</td><td>testing, evaluation, observability, security, cost, deployment, version axes</td><td>02–06</td><td>five kinds of evidence; five rollback-able, traceable axes</td></tr><tr><td><a href="./09-advanced/">09-advanced</a> Advanced (bridge)</td><td>Where do I learn the deep water?</td><td>interpretability, reasoning &amp; TTC, MoE &amp; frontier architectures, multimodal</td><td>as needed</td><td>knows the stopping points and which Learn LLM chapter to jump to</td></tr><tr><td><a href="./appendices/">Appendices</a></td><td>What else is there to read?</td><td>training bridges, cases, course notes, methodology archive</td><td>outside the spine</td><td>off-spine reading with a home</td></tr><tr><td><a href="./../cookbook/">Recipes</a></td><td>What can I copy for this task?</td><td>snippet-level code recipes</td><td>all groups</td><td>open and copy</td></tr><tr><td><a href="./../resources.html">Resource Library</a></td><td>Which resource for which problem?</td><td>a research index of symptom → chapter → resource</td><td>all groups</td><td>arrive with a question, leave with the next question</td></tr></tbody></table><h3 id="symptom-driven-decision-tree" tabindex="-1">Symptom-driven decision tree <a class="header-anchor" href="#symptom-driven-decision-tree" aria-label="Permalink to &quot;Symptom-driven decision tree&quot;">​</a></h3><p>Start from symptoms, not nouns. Find your symptom and enter the matching group:</p><table tabindex="0"><thead><tr><th>Your symptom</th><th>Where to go</th></tr></thead><tbody><tr><td>Output is unstable / unparseable</td><td><a href="./03-context/">03-context</a> (landing point: <a href="./02-inference-interface/structured-output.html">structured output</a>)</td></tr><tr><td>Answers are stable but not yet integrated into a product</td><td><a href="./02-inference-interface/">02-inference-interface</a></td></tr><tr><td>Answers lack private or fresh facts</td><td><a href="./04-grounding/">04-grounding</a></td></tr><tr><td>Need to call systems or execute actions</td><td><a href="./05-action/">05-action</a>; multi-step / recoverable / approval-gated → then <a href="./06-agent-systems/">06-agent-systems</a></td></tr><tr><td>Need to collaborate across host / org / agent boundaries</td><td><a href="./07-interoperability/">07-interoperability</a> (pick by connection direction)</td></tr><tr><td>Feature runs, but cannot be proven / operated</td><td><a href="./08-production/">08-production</a></td></tr><tr><td>Want to understand model internals / training / frontier architectures</td><td><a href="./01-model-lifecycle/">01-model-lifecycle</a> and <a href="./09-advanced/">09-advanced</a> (bridges → Learn LLM)</td></tr></tbody></table>',7)),a(s),e[3]||(e[3]=t('<h3 id="what-this-repo-does-not-teach-three-boundaries" tabindex="-1">What this repo does not teach (three boundaries) <a class="header-anchor" href="#what-this-repo-does-not-teach-three-boundaries" aria-label="Permalink to &quot;What this repo does not teach (three boundaries)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Not expanded here</th><th>canonical owner</th><th>What this repo keeps</th></tr></thead><tbody><tr><td>Model internals: Transformer, training math, KV-cache derivations</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a></td><td>decision impact + stopping points + jumps, see <a href="./00-map/site-boundaries.html">Site Boundaries</a></td></tr><tr><td>Evaluation methodology: benchmarks, judges, release evidence</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a></td><td>when evidence is needed + how to wire gates into release</td></tr><tr><td>Vendor docs / blog capture and EPUB indexing</td><td>sites-epub (<a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">epub.zenheart.site</a>)</td><td>second-pass treatment of stable cross-vendor concepts + reading routes</td></tr></tbody></table><h3 id="when-to-use-when-not-to" tabindex="-1">When to use / when not to <a class="header-anchor" href="#when-to-use-when-not-to" aria-label="Permalink to &quot;When to use / when not to&quot;">​</a></h3><ul><li>Use: entering this track for the first time, unsure what to learn, or looking for an entry point from a concrete symptom.</li><li>Do not use: model internals (→ <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>); vendor product click-paths (→ Products); evaluation methodology (→ <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>).</li></ul><p>Historical milestone: this map was restructured in 2026-09 under Issue #116 Scope v6 into the <strong>ten-group dependency-driven</strong> form (two chains converge / read-write split / protocols by direction); the v5 six-layer pyramid (capability-transformation chain) narrative is superseded, while its &quot;symptom decision tree + two-hop drills + three-station boundaries&quot; carry over. Earlier history is unverified; nothing is invented.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>This is a map page and produces no runnable artifact; &quot;usage&quot; = navigation drills. The acceptance bar is one line: <strong>from a symptom, reach the correct group within two hops.</strong></p><h3 id="drill-1-unstable-output" tabindex="-1">Drill 1: unstable output <a class="header-anchor" href="#drill-1-unstable-output" aria-label="Permalink to &quot;Drill 1: unstable output&quot;">​</a></h3><ul><li><strong>Symptom</strong>: &quot;The model&#39;s JSON fails to parse three times out of ten.&quot;</li><li><strong>Hop 1</strong>: decision tree above → &quot;output unstable / unparseable&quot; → <a href="./03-context/">03-context</a>.</li><li><strong>Hop 2</strong>: the group&#39;s symptom routing → the landing point for output-shape problems is <a href="./02-inference-interface/structured-output.html">structured output</a> (a contract-family page hosted in group 02).</li><li><strong>Arrival</strong>: you can write and validate an output schema and know how failure is accepted.</li></ul><h3 id="drill-2-missing-fresh-facts" tabindex="-1">Drill 2: missing fresh facts <a class="header-anchor" href="#drill-2-missing-fresh-facts" aria-label="Permalink to &quot;Drill 2: missing fresh facts&quot;">​</a></h3><ul><li><strong>Symptom</strong>: &quot;The internal assistant doesn&#39;t know the refund policy we updated last week.&quot;</li><li><strong>Hop 1</strong>: decision tree → &quot;answers lack private or fresh facts&quot; → <a href="./04-grounding/">04-grounding</a>.</li><li><strong>Hop 2</strong>: the group&#39;s topic table → <a href="./04-grounding/rag.html">RAG</a>.</li><li><strong>Arrival</strong>: you can build a traceable retrieval chain and update path (reading the world: the failure mode is answering wrongly, not breaking things).</li></ul><h3 id="drill-3-wanting-the-system-to-act" tabindex="-1">Drill 3: wanting the system to act <a class="header-anchor" href="#drill-3-wanting-the-system-to-act" aria-label="Permalink to &quot;Drill 3: wanting the system to act&quot;">​</a></h3><ul><li><strong>Symptom</strong>: &quot;I want the agent to auto-resolve finished tickets, but I&#39;m afraid it will change the wrong thing.&quot;</li><li><strong>Hop 1</strong>: decision tree → &quot;need to call systems or execute actions&quot; → <a href="./05-action/">05-action</a>.</li><li><strong>Hop 2</strong>: single controlled actions → <a href="./05-action/tool-execution.html">tool execution</a>; multi-step / recoverable / approval-gated → <a href="./06-agent-systems/">Agent Runtime</a>.</li><li><strong>Arrival</strong>: you can restrict permissions and make actions idempotent and reversible (writing the world: the acceptance criterion is restricted permissions, not correct citations).</li></ul><p>If none of the three works: read the <a href="./00-map/complexity-ladder.html">Complexity Decision Ladder</a> to pin down your requirement level, then return to the decision tree.</p><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="why-organize-by-dependency-not-taxonomy" tabindex="-1">Why organize by dependency, not taxonomy <a class="header-anchor" href="#why-organize-by-dependency-not-taxonomy" aria-label="Permalink to &quot;Why organize by dependency, not taxonomy&quot;">​</a></h3><p>The old directory once put Fundamentals (knowledge abstraction), Prompt (interaction means), Integrate (implementation), RAG / Agent (architecture patterns), Skills / MCP (assets/protocols), and Engineering (lifecycle) on one level — six classification axes mixed, so readers could not get from &quot;where I&#39;m stuck&quot; to &quot;which page to read&quot;. This map keeps one spine: <strong>knowledge ordered by dependency, not filed by noun</strong>. Each group answers one question with declared dependencies and exits; the other dimensions (trust domain, lifecycle, evidence level, ownership) are demoted to page metadata and reference tables instead of competing as top-level sections.</p><h3 id="the-convergence-why-the-first-engineering-topic-is-the-interface-not-the-model" tabindex="-1">The convergence: why the first engineering topic is the interface, not the model <a class="header-anchor" href="#the-convergence-why-the-first-engineering-topic-is-the-interface-not-the-model" aria-label="Permalink to &quot;The convergence: why the first engineering topic is the interface, not the model&quot;">​</a></h3><p>Your code starts at Inference, not at the Transformer. The left chain (model lifecycle) determines &quot;what the model is and can do&quot;; the right chain (systems engineering) determines &quot;what you build with it&quot; — the convergence point is Inference / Model Interface. Hence the first engineering group is <a href="./02-inference-interface/">Inference &amp; Interface</a>, with model-side knowledge attached upstream as a <a href="./01-model-lifecycle/">bridge</a>.</p><h3 id="the-read-write-split-two-opposite-failure-modes" tabindex="-1">The read/write split: two opposite failure modes <a class="header-anchor" href="#the-read-write-split-two-opposite-failure-modes" aria-label="Permalink to &quot;The read/write split: two opposite failure modes&quot;">​</a></h3><p>Grounding and Action share the intuition &quot;connect the model to the outside world&quot;, but their acceptance criteria are opposite: a read fails by <strong>answering wrongly or failing to refuse</strong> (no side effects) — accept correct citations and correct refusals; a write fails by <strong>corrupting state</strong> (side effects) — accept restricted permissions and recoverability. Merging them into one group dilutes both acceptance regimes — this is the root cause of the 04/05 split, and the shared structure behind the two engineering instincts &quot;retrieve before you generate&quot; and &quot;allowlist before you execute&quot;.</p><h3 id="teaching-order-is-not-runtime-dependency" tabindex="-1">Teaching order is not runtime dependency <a class="header-anchor" href="#teaching-order-is-not-runtime-dependency" aria-label="Permalink to &quot;Teaching order is not runtime dependency&quot;">​</a></h3><p>Arrows represent the default learning and dependency progression for newcomers. Real engineering can be built bottom-up from contracts and fixtures; Grounding, Action, and interface concerns combine per scenario. Each group&#39;s index states both &quot;what to learn first by default&quot; and &quot;which scenarios may skip it&quot;.</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>This page wires no code; &quot;development&quot; = how to maintain this map.</p><h3 id="maintenance-flow" tabindex="-1">Maintenance flow <a class="header-anchor" href="#maintenance-flow" aria-label="Permalink to &quot;Maintenance flow&quot;">​</a></h3><ol><li><strong>Register</strong>: a new topic is first registered in <code>_phase0/slug-map.json</code> with topicId, group, slug, and mergeSources; one topicId has exactly one canonical owner.</li><li><strong>Assign group</strong>: by &quot;what question this page answers, what it depends on, who its exit serves&quot; — never by technology noun. If it fits no group, ask first whether it is Products / appendices / sibling content.</li><li><strong>Rewire</strong>: after a topic joins a group, return here to check: does the decision tree need a new branch? Does the ten-group table&#39;s core-topics column need a word?</li><li><strong>Bilingual</strong>: zh/en pages match on topicId, structure, conclusions, diagrams, links; only <code>bilingualParity: exact</code> counts as done.</li><li><strong>Close out</strong>: merged-away old paths go into <code>docs/public/redirects.json</code>, not the sidebar.</li></ol><h3 id="inventory-and-acceptance" tabindex="-1">Inventory and acceptance <a class="header-anchor" href="#inventory-and-acceptance" aria-label="Permalink to &quot;Inventory and acceptance&quot;">​</a></h3><ul><li>Structural facts follow <code>node scripts/pyramid-inventory.mjs</code> output, never memory; this page&#39;s body must contain all ten group directory names (00-map … 09-advanced).</li><li>Map-level acceptance: from any real symptom, reach the correct group within two hops; any orphan page, owner-less protocol page, or link-only resource card without problem context counts as a map defect.</li></ul><h3 id="maintenance-anti-patterns" tabindex="-1">Maintenance anti-patterns <a class="header-anchor" href="#maintenance-anti-patterns" aria-label="Permalink to &quot;Maintenance anti-patterns&quot;">​</a></h3><ul><li>Using &quot;More&quot; to collect what fits nowhere — trash-can taxonomy re-pollutes the dependency spine.</li><li>Adding a top-level entry for a hot protocol — protocols always enter from a connection direction.</li><li>zh/en pages evolving separately — any <code>bilingualParity: partial</code> lasting more than one writing cycle is a defect.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>This is an entry page; resources are &quot;next hops&quot;. Four levels:</p><ul><li><strong>Beginner</strong>: read this page + the <a href="./00-map/complexity-ladder.html">Complexity Decision Ladder</a>; locate your group.</li><li><strong>Builder</strong>: enter <a href="./03-context/">03-context</a> and <a href="./02-inference-interface/">02-inference-interface</a>; finish your first key-free fixture.</li><li><strong>Operator</strong>: enter <a href="./08-production/">08-production</a>; learn to prove launch-readiness with evidence and version axes.</li><li><strong>Researcher</strong>: descend to sibling sites for deep internals (the bridge pages of <a href="./01-model-lifecycle/">01</a> and <a href="./09-advanced/">09</a> are the entrances).</li></ul><h3 id="three-station-entry-table" tabindex="-1">Three-station entry table <a class="header-anchor" href="#three-station-entry-table" aria-label="Permalink to &quot;Three-station entry table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Site</th><th>canonical URL</th><th>Use</th><th>Status</th></tr></thead><tbody><tr><td>Learn LLM</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a></td><td>model internals, training math</td><td>HTTP 200 (retrievedAt 2026-09-01)</td></tr><tr><td>Learn LLM chapter directory</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/</a></td><td>the 21-chapter book map, deep-link entrance</td><td>HTTP 200 (retrievedAt 2026-09-01)</td></tr><tr><td>evals</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>evaluation methods, benchmarks, release evidence</td><td>HTTP 200 (retrievedAt 2026-09-01)</td></tr><tr><td>sites-epub</td><td><a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a></td><td>vendor-source capture and EPUB indexing</td><td>warning: TLS certificate mismatch, HTTPS currently unreachable (retrievedAt 2026-09-01, re-check before citing)</td></tr></tbody></table><p>Division of labor, stopping points, and bridge metadata conventions: see <a href="./00-map/site-boundaries.html">Site Boundaries and Knowledge Ownership</a>.</p><h3 id="falsification-and-open-questions" tabindex="-1">Falsification and open questions <a class="header-anchor" href="#falsification-and-open-questions" aria-label="Permalink to &quot;Falsification and open questions&quot;">​</a></h3><ul><li>If a symptom finds no branch on the decision tree, or a branch delivers you to the wrong group — that is a map defect; fix the map first rather than routing around it.</li><li>Open: sites-epub is currently unreachable over HTTPS (certificate mismatch); its ownership claim stands as recorded in bridge-register pending restoration.</li><li>Open: the group indexes of <a href="./05-action/">05-action</a> and <a href="./06-agent-systems/">06-agent-systems</a> are being filled in by parallel tasks during the v6 migration; references here follow the group directories.</li></ul><h3 id="where-learn-ai-stops-where-to-go-next" tabindex="-1">Where learn-ai stops / where to go next <a class="header-anchor" href="#where-learn-ai-stops-where-to-go-next" aria-label="Permalink to &quot;Where learn-ai stops / where to go next&quot;">​</a></h3><ul><li>How models &quot;think&quot;: the <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">chapter directory</a> of <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>.</li><li>How to prove quality: <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>.</li><li>Vendor sources and offline reading: sites-epub (once restored).</li><li>Next stop in this repo: the <a href="./00-map/complexity-ladder.html">Complexity Decision Ladder</a>.</li></ul>',41))])}const T=d(u,[["render",g]]);export{A as __pageData,T as default};
